"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["79671"],{87994(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.base_legal_obrigatoria","status":422,"titulo":"Base legal da modalidade \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.base_legal_obrigatoria","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada n\xe3o tem `baseLegal`, ou tem o campo vazio. A base\\nlegal identifica o dispositivo \u2014 lei, decreto, resolu\xe7\xe3o \u2014 que fundamenta a\\nexist\xeancia da modalidade, seja ela ampla concorr\xeancia, cota reservada da Lei\\n12.711, ou uma modalidade institucional pr\xf3pria da Unifesspa.","**`baseLegal` n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014\\n\xe9 copiada do cadastro de modalidades de Configura\xe7\xe3o, no momento em que a\\nmodalidade \xe9 selecionada (`IModalidadeReader`). Diferente da maioria dos\\noutros campos obrigat\xf3rios desta s\xe9rie, **o cadastro de Configura\xe7\xe3o n\xe3o\\nexige base legal** \u2014 o campo \xe9 opcional l\xe1 (`string?`, sem confer\xeancia de\\nobrigatoriedade em `Modalidade.Criar`/`Atualizar`, s\xf3 um limite de tamanho).\\nUma modalidade cadastrada sem base legal \xe9 aceita normalmente em\\nConfigura\xe7\xe3o; \xe9 s\xf3 ao ser **selecionada** numa distribui\xe7\xe3o de vagas que a\\naus\xeancia \xe9 recusada. Este n\xe3o \xe9 um cen\xe1rio de dado corrompido \u2014 \xe9 o\\ncaminho comum para quem cadastrou uma modalidade sem preencher esse campo.","N\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira que falhar que\\ninterrompe a cria\xe7\xe3o da modalidade."],"comoResolver":["Preencha o campo `baseLegal` da modalidade no cadastro de Configura\xe7\xe3o \u2014\\nn\xe3o \xe9 poss\xedvel inform\xe1-lo pelo corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de\\nvagas, que n\xe3o recebe esse campo \u2014 e tente selecionar a modalidade de novo."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);